const events=window.ARCHIVE_EVENTS;const $=s=>document.querySelector(s);let selected=events[0],year='all',language='both',demoTimer=null,demoIndex=0,player=null,tracks={zh:[],en:[]},lastKey='',apiReady=false;const sample=[{zh:'每一次突破，都從一個問題開始。',en:'Every breakthrough begins with a question.'},{zh:'回看那些，讓未來更靠近的時刻。',en:'Revisit the moments that brought the future closer.'},{zh:'兩種語言，同一份好奇心。',en:'Two languages. One shared curiosity.'}];
