function render(){const q=$('#search').value.trim().toLowerCase();const found=events.filter(e=>(year==='all'||e.date.startsWith(year))&&`${e.title} ${e.en}`.toLowerCase().includes(q));$('#grid').innerHTML=found.map(e=>`<button class="card" data-id="${e.id}" aria-label="${esc(e.title)}，${dateLabel(e.date)}，觀看重播"><span class="card-image">${e.video||e.image?`<img loading="lazy" src="${esc(thumbnail(e))}" alt="${esc(e.title)}影片封面">`:`<span class="source-poster">${esc(e.en)}</span>`}<span class="card-play">▶</span></span><span class="card-date">${dateLabel(e.date)}</span><span class="card-title">${esc(e.title)}</span><span class="card-en">${esc(e.en)}</span><span class="card-meta"><span class="replay">觀看重播</span><span>${hasSaved(e.id)?'已匯入字幕':'字幕待補'}</span></span></button>`).join('');$('#empty').hidden=found.length!==0;$('#record-count').textContent=`${found.length} 場已整理`;document.querySelectorAll('.card').forEach(b=>b.onclick=()=>selectEvent(b.dataset.id));document.querySelectorAll('.card-image img').forEach(img=>img.onerror=()=>{const p=document.createElement('span');p.className='source-poster';p.textContent=img.alt.replace('影片封面','');img.replaceWith(p);});}
function hasSaved(id){try{return !!localStorage.getItem('live-subs-'+id);}catch{return false;}}function readTracks(){tracks={zh:[],en:[]};try{const data=JSON.parse(localStorage.getItem('live-subs-'+selected.id));if(data&&Array.isArray(data.zh)&&Array.isArray(data.en))tracks=data;}catch{}$('#offset').value=0;updateStatus();}function updateStatus(msg){$('#subtitle-status').textContent=msg||(tracks.zh.length||tracks.en.length?`已載入 ${tracks.zh.length} 段中文、${tracks.en.length} 段英文字幕。播放影片即可同步顯示。`:(selected.video?'本片尚未附上中英字幕，可先預覽特效。':'本片透過官方頁面觀看；此處可預覽字幕特效。'));}
