function setLanguage(value){if(!['both','zh','en','off'].includes(value))throw Error('不支援的字幕語言');language=value;document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===value)));lastKey='';if(demoTimer)showCaption(sample[demoIndex],true);else syncCaptions();return {language};}
function showCaption(cue,isDemo){if(!cue||language==='off'){$('#captions').hidden=true;return;}$('#captions').hidden=false;$('#demo-label').hidden=!isDemo;const effect=$('#effect').value;for(const key of ['zh','en']){const el=$('#caption-'+key);el.className=`caption-${key} effect-${effect}`;const text=(language==='both'||language===key)?cue[key]||'':'';el.replaceChildren();if(effect==='reveal'){const parts=key==='zh'?Array.from(text):text.split(/(\s+)/);parts.forEach((word,i)=>{const s=document.createElement('span');s.textContent=word;s.style.setProperty('--delay',Math.min(i*.04,1.1)+'s');el.append(s);});}else el.textContent=text;}}
function stopDemo(){if(demoTimer)clearInterval(demoTimer);demoTimer=null;$('#demo').innerHTML='<span class="spark">✧</span> 預覽字幕特效';$('#captions').hidden=true;lastKey='';}$('#demo').onclick=()=>{if(demoTimer){stopDemo();return;}if(player?.pauseVideo)player.pauseVideo();demoIndex=0;showCaption(sample[0],true);$('#demo').textContent='停止特效預覽';demoTimer=setInterval(()=>{demoIndex=(demoIndex+1)%sample.length;showCaption(sample[demoIndex],true);},4200);};document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>setLanguage(b.dataset.lang));$('#effect').onchange=()=>{lastKey='';if(demoTimer)showCaption(sample[demoIndex],true);else syncCaptions();};document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{year=b.dataset.year;document.querySelectorAll('[data-year]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.year===year)));render();});$('#search').oninput=render;
window.onYouTubeIframeAPIReady=()=>{apiReady=true;};$('#play').onclick=()=>{stopDemo();if(!selected.video){window.open(selected.source,'_blank','noopener');return;}if(!apiReady||!window.YT?.Player){updateStatus('播放器仍在載入，請稍後重試，或使用下方 YouTube 連結觀看。');return;}$('#play').hidden=true;$('.poster-label').hidden=true;player=new YT.Player('yt-player',{videoId:selected.video,host:'https://www.youtube-nocookie.com',playerVars:{autoplay:1,rel:0,playsinline:1,origin:location.origin},events:{onReady:ev=>ev.target.playVideo(),onStateChange:ev=>{if(ev.data===1&&demoTimer)stopDemo();},onError:()=>updateStatus('此影片暫時無法在站內播放，請使用下方官方影片連結。')}});};const api=document.createElement('script');api.src='https://www.youtube.com/iframe_api';api.onerror=()=>updateStatus('播放器連線未成功，可使用下方官方影片連結觀看。');document.head.append(api);
function syncCaptions(){if(demoTimer)return;if(!player?.getCurrentTime){$('#captions').hidden=true;return;}const t=player.getCurrentTime()-Number($('#offset').value||0);const zh=tracks.zh.find(c=>t>=c.start&&t<c.end);const en=tracks.en.find(c=>t>=c.start&&t<c.end);const key=`${language}|${$('#effect').value}|${zh?.start}|${en?.start}`;if(key===lastKey)return;lastKey=key;showCaption(zh||en?{zh:zh?.text||'',en:en?.text||''}:null,false);}setInterval(syncCaptions,150);
function parseSubtitles(text){const ts=s=>{const p=s.replace(',','.').split(':').map(Number);return p.length===3?p[0]*3600+p[1]*60+p[2]:p[0]*60+p[1];};const cues=[];const normalized=text.replace(/^\uFEFF/,'').replace(/\r/g,'');for(const block of normalized.split(/\n\s*\n/)){const lines=block.split('\n');const i=lines.findIndex(l=>l.includes('-->'));if(i<0)continue;const match=lines[i].match(/((?:\d{1,2}:)?\d{2}:\d{2}[.,]\d{3})\s*-->\s*((?:\d{1,2}:)?\d{2}:\d{2}[.,]\d{3})/);if(!match)continue;const start=ts(match[1]),end=ts(match[2]);const body=lines.slice(i+1).join('\n').replace(/<[^>]*>/g,'').trim();if(Number.isFinite(start)&&end>start&&body)cues.push({start,end,text:body});}return cues.sort((a,b)=>a.start-b.start);}
for(const lang of ['zh','en'])$('#'+lang+'-file').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;const eventId=selected.id;if(file.size>5*1024*1024){updateStatus('請選擇小於 5 MB 的字幕檔。');return;}const cues=parseSubtitles(await file.text());if(selected.id!==eventId)return;if(!cues.length){updateStatus('找不到有效的時間碼，請檢查 SRT／VTT 格式。');return;}stopDemo();tracks[lang]=cues;try{localStorage.setItem('live-subs-'+selected.id,JSON.stringify(tracks));updateStatus();}catch{updateStatus('字幕已載入；瀏覽器儲存空間不足，重新開啟後需再次匯入。');}lastKey='';render();};$('#clear-subs').onclick=()=>{tracks={zh:[],en:[]};try{localStorage.removeItem('live-subs-'+selected.id);}catch{}$('#zh-file').value='';$('#en-file').value='';stopDemo();updateStatus();render();};$('#offset').oninput=()=>{lastKey='';syncCaptions();};readTracks();render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'select_livestream',title:'選擇直播',description:'選擇已整理的直播並更新播放器與字幕控制，不會自動播放。',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.id!=='string')throw Error('請提供直播 id');return selectEvent(input.id);}},{name:'configure_subtitle_language',title:'設定字幕語言',description:'設定播放器字幕為中英雙語、中文、英文或關閉。',inputSchema:{type:'object',properties:{language:{type:'string',enum:['both','zh','en','off']}},required:['language'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){return setLanguage(input?.language);}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
